-- Company identity and document branding, independent of the Architect product brand.
-- Existing accounting rows and documents are never rewritten by this migration.
alter table public.company_settings
 add column legal_name text not null default '',
 add column address text not null default '',
 add column tax_id text not null default '',
 add column phone text not null default '',
 add column email text not null default '',
 add column website text not null default '',
 add column logo_data text not null default '',
 add column document_primary text not null default '#18324A',
 add column document_secondary text not null default '#087C8B',
 add column configured boolean not null default false,
 add column company_version integer not null default 0,
 add column localization_country text,
 add column localization_version text,
 add constraint company_identity_lengths check(length(legal_name)<=200 and length(address)<=500 and length(tax_id)<=80 and length(phone)<=60 and length(email)<=254 and length(website)<=300 and length(logo_data)<=800000),
 add constraint company_identity_colors check(document_primary ~ '^#[0-9A-Fa-f]{6}$' and document_secondary ~ '^#[0-9A-Fa-f]{6}$');
revoke all on public.company_settings from anon,authenticated;
grant select on public.company_settings to authenticated;
drop policy company_settings_read on public.company_settings;
create policy company_settings_read on public.company_settings for select to authenticated
 using ((select auth.uid()) is not null and (select private.current_user_role()) is not null);

alter table public.accounting_accounts add column localization_country text,add column localization_source_code text;
create unique index accounting_localization_account on public.accounting_accounts(localization_country,localization_source_code) where localization_country is not null;
create table private.company_localization_templates(country text primary key,template jsonb not null);
revoke all on private.company_localization_templates from public,anon,authenticated;
