 'phone',c.phone,'email',c.email,'website',c.website,'country',c.country,'currency',c.currency,
 'logo_data',c.logo_data,'document_primary',c.document_primary,'document_secondary',c.document_secondary,
 'configured',c.configured,'company_version',c.company_version,'localization_country',c.localization_country,'localization_version',c.localization_version)
$$;
revoke all on function private.gama_company_public(public.company_settings) from public,anon,authenticated;

create function private.gama_company_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if old.localization_country is not null and new.country<>old.country then raise exception 'COMPANY_LOCALIZATION_LOCKED';end if;
 new.company_version:=old.company_version+1;return new;
end $$;
revoke all on function private.gama_company_guard() from public,anon,authenticated;
create trigger company_identity_guard before update on public.company_settings for each row execute function private.gama_company_guard();

-- The audit records changes without duplicating the embedded image on each save.
create function private.gama_company_audit() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into public.gama_audit(table_name,row_id,action,actor_id,actor_role,old_data,new_data,changed_fields)
 values('company_settings','true',tg_op,auth.uid(),private.current_user_role(),
 (to_jsonb(old)-'logo_data')||jsonb_build_object('logo_fingerprint',md5(old.logo_data)),
 (to_jsonb(new)-'logo_data')||jsonb_build_object('logo_fingerprint',md5(new.logo_data)),
 array(select k from jsonb_object_keys(to_jsonb(new)) k where to_jsonb(new)->k is distinct from to_jsonb(old)->k));
 return new;
end $$;
revoke all on function private.gama_company_audit() from public,anon,authenticated;
drop trigger if exists ac_audit_company_settings on public.company_settings;
create trigger ac_audit_company_settings after update on public.company_settings for each row execute function private.gama_company_audit();

create function private.gama_company_localize(p_country text) returns void
language plpgsql security definer set search_path='' as $$
declare cfg public.company_settings;t jsonb;a jsonb;tx jsonb;ids jsonb:='{}';v_code text;account_id uuid;target text;
begin
 if auth.uid() is null or private.current_user_role() is distinct from 'administrador' then raise exception 'COMPANY_ADMIN_REQUIRED';end if;
 select * into cfg from public.company_settings where id for update;
 if cfg.localization_country=p_country then return;end if;
 if cfg.localization_country is not null then raise exception 'COMPANY_LOCALIZATION_LOCKED';end if;
 select template into t from private.company_localization_templates where country=p_country;
 if t is null then raise exception 'COMPANY_LOCALIZATION_UNSUPPORTED';end if;
 lock table public.accounting_entries in share row exclusive mode;
 if exists(select 1 from public.accounting_entries) then raise exception 'COMPANY_LEDGER_NOT_EMPTY';end if;
 for a in select value from jsonb_array_elements(t->'accounts') loop
  v_code:=a->>'code';
  -- A legacy account can have the same number with a different meaning. Preserve
  -- that account and its references; keep the original national number in metadata.
  if exists(select 1 from public.accounting_accounts ac where ac.code=v_code) then v_code:=p_country||'-'||v_code;end if;
  if exists(select 1 from public.accounting_accounts ac where ac.code=v_code) then raise exception 'COMPANY_ACCOUNT_CODE_CONFLICT: %',v_code;end if;
  insert into public.accounting_accounts(code,name,type,active,is_system,localization_country,localization_source_code)
  values(v_code,a->>'name',a->>'type',coalesce((a->>'active')::boolean,true),false,p_country,a->>'code') returning id into account_id;
  ids:=ids||jsonb_build_object(a->>'code',account_id);
 end loop;
 for tx in select value from jsonb_array_elements(t->'taxes') loop
  -- Never overwrite a rate already entered manually.
  if exists(select 1 from public.accounting_taxes atx where atx.code=tx->>'code' and (atx.rate<>(tx->>'rate')::numeric or atx.country is distinct from p_country)) then raise exception 'COMPANY_TAX_CODE_CONFLICT';end if;
  insert into public.accounting_taxes(code,name,rate,kind,country,valid_from,collected_account_id,deductible_account_id)
  values(tx->>'code',tx->>'name',(tx->>'rate')::numeric,'both',p_country,current_date,
  (ids->>(t->'mapping'->>'tax_collected'))::uuid,(ids->>(t->'mapping'->>'tax_deductible'))::uuid)
  on conflict(code) do nothing;
 end loop;
 update public.company_settings set country=p_country,
 receivable_account_id=(ids->>(t->'mapping'->>'receivable'))::uuid,
 payable_account_id=(ids->>(t->'mapping'->>'payable'))::uuid,
 sales_account_id=(ids->>(t->'mapping'->>'sales'))::uuid,
 purchase_account_id=(ids->>(t->'mapping'->>'purchase'))::uuid,
 tax_collected_account_id=(ids->>(t->'mapping'->>'tax_collected'))::uuid,
 tax_deductible_account_id=(ids->>(t->'mapping'->>'tax_deductible'))::uuid,
 localization_country=p_country,localization_version=t->>'version',updated_at=now(),updated_by=auth.uid() where id;
end $$;
revoke all on function private.gama_company_localize(text) from public,anon,authenticated;

create function private.gama_company_action(p_action text,p_data jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare cfg public.company_settings;v_country text;v_currency text;logo text;bytes bytea;result jsonb;
begin
 if auth.uid() is null or private.current_user_role() is null then raise exception 'AUTH_REQUIRED';end if;
 if p_action='get' then
  select * into cfg from public.company_settings where id;
  return private.gama_company_public(cfg);
 end if;
 if private.current_user_role()<>'administrador' then raise exception 'COMPANY_ADMIN_REQUIRED';end if;
 if p_action='options' then
  return jsonb_build_object('ledger_empty',not exists(select 1 from public.accounting_entries),'templates',
   (select jsonb_agg((template-'accounts'-'mapping')||jsonb_build_object('account_count',jsonb_array_length(template->'accounts')) order by country) from private.company_localization_templates));
 end if;
 if p_action<>'save' then raise exception 'COMPANY_ACTION_INVALID';end if;
 if jsonb_typeof(p_data)<>'object' then raise exception 'COMPANY_INVALID';end if;
 select * into cfg from public.company_settings where id for update;
 if (p_data->>'company_version')::integer is distinct from cfg.company_version then raise exception 'COMPANY_STALE';end if;
 if length(btrim(coalesce(p_data->>'legal_name',''))) not between 1 and 200 then raise exception 'COMPANY_NAME_REQUIRED';end if;
 v_country:=upper(btrim(coalesce(p_data->>'country',cfg.country)));v_currency:=upper(btrim(coalesce(p_data->>'currency',cfg.currency)));
 if v_country!~'^[A-Z]{2}$' or v_currency!~'^[A-Z]{3}$' then raise exception 'COMPANY_INVALID';end if;
 if coalesce(p_data->>'email','')<>'' and p_data->>'email'!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'COMPANY_EMAIL_INVALID';end if;
 if coalesce(p_data->>'website','')<>'' and p_data->>'website'!~*'^https?://[^[:space:]]+$' then raise exception 'COMPANY_WEBSITE_INVALID';end if;
 logo:=coalesce(p_data->>'logo_data',cfg.logo_data);
 if length(logo)>800000 then raise exception 'COMPANY_LOGO_TOO_LARGE';end if;
 if logo<>'' then
  if logo!~'^data:image/(png|jpeg);base64,[A-Za-z0-9+/]+=*$' then raise exception 'COMPANY_LOGO_INVALID';end if;
  bytes:=decode(split_part(logo,',',2),'base64');
  if length(bytes)<32 or not ((logo like 'data:image/png;%' and substring(bytes from 1 for 8)=decode('89504e470d0a1a0a','hex')) or (logo like 'data:image/jpeg;%' and substring(bytes from 1 for 3)=decode('ffd8ff','hex'))) then raise exception 'COMPANY_LOGO_INVALID';end if;
 end if;
 if coalesce((p_data->>'install_localization')::boolean,false) then perform private.gama_company_localize(v_country);end if;
 update public.company_settings set
 legal_name=btrim(p_data->>'legal_name'),address=btrim(coalesce(p_data->>'address','')),tax_id=btrim(coalesce(p_data->>'tax_id','')),
 phone=btrim(coalesce(p_data->>'phone','')),email=btrim(coalesce(p_data->>'email','')),website=btrim(coalesce(p_data->>'website','')),
 country=v_country,currency=v_currency,logo_data=logo,document_primary=coalesce(p_data->>'document_primary',cfg.document_primary),
 document_secondary=coalesce(p_data->>'document_secondary',cfg.document_secondary),configured=true,updated_at=now(),updated_by=auth.uid()
 where id returning * into cfg;
 return private.gama_company_public(cfg);
end $$;
revoke all on function private.gama_company_action(text,jsonb) from public,anon;
grant execute on function private.gama_company_action(text,jsonb) to authenticated;
create function public.gama_company_action(p_action text,p_data jsonb default '{}') returns jsonb
language sql security invoker set search_path='' as $$select private.gama_company_action(p_action,p_data)$$;
revoke all on function public.gama_company_action(text,jsonb) from public,anon;
grant execute on function public.gama_company_action(text,jsonb) to authenticated;
